import XCTest
@MainActor final class CompanionUnlockJourneyTests:XCTestCase {
 private func tap(_ id:String,_ app:XCUIApplication){let b=app.buttons[id];XCTAssertTrue(b.waitForExistence(timeout:15),id);XCTAssertTrue(b.isHittable,id);b.tap()}
 private func photo(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
 private func journey(equip:Bool){
  continueAfterFailure=false;let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_ENTRY_INITIAL_LANGUAGE":"en","PIYALI_ENTRY_INITIAL_THEME":"light","PIYALI_SETTINGS_FIXTURE":"1","PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_FLASHCARD_FIXTURE":"1","PIYALI_COMPANION_UNLOCK_FIXTURE":"1"];app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();let entry=app.textFields["entryName"];XCTAssertTrue(entry.waitForExistence(timeout:15));entry.tap();entry.typeText("Unlock Learner");tap("entryKeyboardDone",app);tap("createAccount",app);XCTAssertTrue(app.buttons["startLearning"].waitForExistence(timeout:15));tap("onboardingPractice",app);tap("onboardingOption-practice-es",app);tap("startLearning",app)
  tap("productMenu",app);tap("productModeMenu",app);tap("productMode-cards",app);tap("flashcardTile-pre-a1-people-1",app);let answer=app.textFields["flashcardAnswer"];XCTAssertTrue(answer.waitForExistence(timeout:8));answer.tap();answer.typeText("mamá\n");XCTAssertTrue(app.staticTexts["flashcardReward"].waitForExistence(timeout:12));XCTAssertTrue(app.staticTexts["flashcardReward"].label.contains("6"));tap("flashcardRate-hard",app)
  XCTAssertTrue(app.buttons["dailyGoalRewardContinue"].waitForExistence(timeout:15));XCTAssertFalse(app.buttons["companionUnlockEquip"].exists);photo("Daily goal precedes companion unlock",app);tap("dailyGoalRewardContinue",app);XCTAssertTrue(app.buttons["companionUnlockEquip"].waitForExistence(timeout:15));photo("Earned Alien unlock",app);app.coordinate(withNormalizedOffset:CGVector(dx:0.005,dy:0.5)).tap();XCTAssertTrue(app.buttons["companionUnlockEquip"].exists,"Outside taps cannot dismiss the source celebration")
  tap(equip ? "companionUnlockEquip":"companionUnlockKeep",app);XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:8));app.terminate();app.launch();tap("productMenu",app);tap("productModeMenu",app);tap("productMode-focus",app);tap("focusCustomizeCompanion",app);XCTAssertTrue(app.buttons["companionOption-"+(equip ? "alien":"ghost")].isSelected);XCTAssertFalse(app.buttons["companionUnlockEquip"].exists);photo(equip ? "Equipped Alien survives relaunch":"Keep current survives relaunch",app)
 }
 func testDailyGoalThenUnlockEquipAndRelaunch(){journey(equip:true)}
 func testDailyGoalThenUnlockKeepAndRelaunch(){journey(equip:false)}
}
